def transform(grid):
    n = len(grid)
    boxes = []
    for r in range(n):
        for c in range(n):
            color = grid[r][c]
            if color == 0:
                continue
            for size in range(4, 10):
                if r + size <= n and c + size <= n:
                    if all(grid[r][x] == color and grid[r + size - 1][x] == color
                           for x in range(c, c + size)) and all(
                           grid[y][c] == color and grid[y][c + size - 1] == color
                           for y in range(r, r + size)):
                        boxes.append((r, c, size, color))
    boxes = sorted(set(boxes))
    panels = [[row[c + 1:c + size - 1] for row in grid[r + 1:r + size - 1]]
              for r, c, size, _ in boxes]

    frame_colors = []
    for row in grid:
        start = 0
        for col in range(1, n + 1):
            if col == n or row[col] != row[start]:
                if col - start >= 20:
                    frame_colors.append(row[start])
                start = col
    out_color = frame_colors[-1] if frame_colors else 2

    a, b = panels[0], panels[1]
    if len(a) == len(b) and len(a[0]) == len(b[0]):
        return [[out_color if (x != 0) != (y != 0) else 0
                 for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]

    # If the panels have different shapes, discard isolated specks and draw
    # the remaining connected pattern in the enclosing frame's color.
    h, w = len(a), len(a[0])
    seen = set()
    components = []
    for i in range(h):
        for j in range(w):
            if a[i][j] == 0 or (i, j) in seen:
                continue
            stack = [(i, j)]
            seen.add((i, j))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and a[yy][xx] != 0 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
            components.append(comp)
    keep = max(components, key=len)
    result = [[0] * w for _ in range(h)]
    for i, j in keep:
        result[i][j] = a[i][j] if (i, j) == (1, 0) else out_color
    return result
